/**
 * 本地 Reicon 图标组件库（由 reicon 迁移脚本生成）
 *
 * 背景：项目原使用 @element-plus/icons-vue，现迁移至 Reicon 图标库。
 * 为最小化侵入，组件名保持与原 EP 组件一致（Close / Document 等），
 * 模板中的 <el-icon><Close /></el-icon> 用法无需改动，仅替换 import 来源。
 *
 * 样式说明：
 *  - 全部使用 Reicon Outline（24×24 网格，细描边，currentColor 可随父级着色）
 *  - Loading 组件基于 reicon refresh 图标 + .reicon-spin 旋转动画（见 src/index.css）
 *  - 通过 <el-icon> 容器控制尺寸与颜色，与 Element Plus 布局无缝兼容
 *
 * 数据源：github.com/dqev/reicon（MIT），生成于 2026-09-04
 */
import { defineComponent, h } from 'vue'

interface IconOptions {
  /** 组件名 */
  name: string
  /** SVG 内部节点（path 等） */
  inner: string
  /** 附加 class */
  className?: string
}

function makeIcon({ name, inner, className }: IconOptions) {
  return defineComponent({
    name,
    inheritAttrs: false,
    setup(_, { attrs }) {
      return () =>
        h(
          'svg',
          {
            xmlns: 'http://www.w3.org/2000/svg',
            viewBox: '0 0 24 24',
            width: '1em',
            height: '1em',
            fill: 'none',
            'aria-hidden': 'true',
            class: className,
            ...attrs,
          },
          [h('g', { innerHTML: inner })]
        )
    },
  })
}


